<template>
  <div class="d-flex flex-row justify-center pa-10 position-relative">
    <v-img
        class="c-img"
        width="260"
        :src="mobile_frame">
    </v-img>
    <div style="width: 100%; scale: 0.62; overflow: hidden; height: 100%" id="checkout-container-mobile"></div>
  </div>
