import mobile_frame from "@/assets/images/phone_frame.svg";

export default {
  name: "MobileWidget",
  props: {
    amount: 0,
    src: '',
    checkoutOptions: {
      type: Object,
      default: {
        options: {
          methods: ["card"],
          methods_disabled: ["wallets"],
          card_icons: ["mastercard", "visa"],
          fields: false,
          full_screen: false,
          button: true,
          hide_title: true,
          hide_link: true,
          email: false,
          theme: {
            type: "light",
            preset: "reset"
          },
          loading:
              "data:image/svg+xml;base64,",
        },
        params: {
          lang: 'en',
          merchant_id: 1549901,
          required_rectoken: "y",
          currency: "GEL"
        },
        css_variable: {
          main: colors.primary,
          card_shadow: '#9ADBE8'
        }
      },
    }
  },
  mounted() {
    this.checkoutOptions.params.amount = this.amount * 100;
    window.checkout("#checkout-container-mobile", this.checkoutOptions);
  },
  data() {
    return {
      mobile_frame: mobile_frame,
      colors: colors,
    };
  },

};
</script>
